"""Validate mAI batch JSONL structure offline, without printing request data."""

from __future__ import annotations

import argparse
import json
import math
import sys
from collections.abc import Sequence
from pathlib import Path
from typing import Any


ENDPOINTS = frozenset({"/v1/responses", "/v1/chat/completions"})


class ValidationError(ValueError):
    """A sanitized structural validation error, not an API schema result."""


def _unique_object(pairs: list[tuple[str, Any]]) -> dict[str, Any]:
    result: dict[str, Any] = {}
    for key, value in pairs:
        if key in result:
            raise ValueError("Duplicate JSON key")
        result[key] = value
    return result


def _reject_constant(value: str) -> None:
    raise ValueError("Non-finite JSON number")


def _finite_float(value: str) -> float:
    number = float(value)
    if not math.isfinite(number):
        raise ValueError("Non-finite JSON number")
    return number


def validate_jsonl(
    path: str | Path, *, endpoint: str, model: str
) -> int:
    """Return the request count or raise a sanitized ValidationError.

    The endpoint and model are caller expectations, not evidence of current
    server support. Provider body schemas and limits are not checked.
    """
    if endpoint not in ENDPOINTS:
        raise ValidationError("Select a supported structural endpoint")
    if not isinstance(model, str) or not model.strip():
        raise ValidationError("Supply a nonblank expected model")

    seen_ids: set[str] = set()
    count = 0
    try:
        with Path(path).open("r", encoding="utf-8") as source:
            for line_number, line in enumerate(source, start=1):
                prefix = f"Line {line_number}: "
                if not line.strip():
                    raise ValidationError(prefix + "blank records are not allowed")
                try:
                    record = json.loads(
                        line,
                        object_pairs_hook=_unique_object,
                        parse_constant=_reject_constant,
                        parse_float=_finite_float,
                    )
                except (ValueError, RecursionError):
                    raise ValidationError(prefix + "invalid strict JSON") from None
                if not isinstance(record, dict):
                    raise ValidationError(prefix + "record must be an object")
                custom_id = record.get("custom_id")
                if not isinstance(custom_id, str) or not custom_id.strip():
                    raise ValidationError(prefix + "custom_id must be a nonblank string")
                if custom_id in seen_ids:
                    raise ValidationError(prefix + "duplicate custom_id")
                if record.get("method") != "POST":
                    raise ValidationError(prefix + "method must be POST")
                if record.get("url") != endpoint:
                    raise ValidationError(prefix + "url must equal the creation endpoint")
                body = record.get("body")
                if not isinstance(body, dict):
                    raise ValidationError(prefix + "body must be an object")
                if body.get("model") != model:
                    raise ValidationError(prefix + "model must equal the expected deployment")
                seen_ids.add(custom_id)
                count += 1
    except (OSError, UnicodeError):
        raise ValidationError("Cannot read input as a UTF-8 JSONL file") from None

    if count == 0:
        raise ValidationError("Input must contain at least one request")
    return count


def main(argv: Sequence[str] | None = None) -> int:
    parser = argparse.ArgumentParser(
        description="Check batch structure offline; this does not verify an API schema."
    )
    parser.add_argument("path", type=Path, help="UTF-8 JSONL input file")
    parser.add_argument("--endpoint", choices=sorted(ENDPOINTS), required=True)
    parser.add_argument("--model", required=True, help="Expected verified deployment name")
    args = parser.parse_args(argv)
    try:
        count = validate_jsonl(args.path, endpoint=args.endpoint, model=args.model)
    except ValidationError as error:
        print(f"Validation failed: {error}", file=sys.stderr)
        return 2
    print(json.dumps({"valid_structure": True, "request_count": count}))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

"""Small, explicit mAI starter. Import and `check` are offline and secret-free."""

import argparse
from dataclasses import dataclass
import os
import sys
from collections.abc import Callable, Mapping
from urllib.parse import urlsplit


ENVIRONMENTS = {
    "DEV": ("azapimdev.worldbank.org", "a1dd6401-acf2-43b5-a37c-c3230ef1be7d/.default"),
    "QA": ("azapimqa.worldbank.org", "c626bd72-9ef7-4efe-9176-5c75800f7670/.default"),
    "PROD": ("azapim.worldbank.org", "0b3b356c-4b5f-4d5b-97ad-c99343ad5557/.default"),
}


class ConfigurationError(ValueError):
    """A safe diagnostic which never includes configuration values."""


@dataclass(frozen=True)
class Config:
    environment: str
    access_type: str
    team_name: str
    host: str
    scope: str
    openai_base_url: str
    model: str


def load_config(environ: Mapping[str, str] | None = None) -> Config:
    values = os.environ if environ is None else environ
    environment = values.get("MAI_ENV", "DEV").strip().upper()
    if environment not in ENVIRONMENTS:
        raise ConfigurationError("MAI_ENV must be DEV, QA, or PROD.")
    access = values.get("MAI_ACCESS_TYPE", "").strip().lower()
    if access not in {"desktop", "application"}:
        raise ConfigurationError("Set MAI_ACCESS_TYPE to desktop or application.")
    team = values.get("MAI_TEAM_NAME", "").strip()
    if not team or any(ord(char) < 32 or ord(char) > 126 for char in team):
        raise ConfigurationError("Set MAI_TEAM_NAME to an approved ASCII header value.")
    host, scope = ENVIRONMENTS[environment]
    base = values.get("MAI_OPENAI_BASE_URL", "").strip()
    if base:
        url = urlsplit(base)
        if (
            url.scheme != "https"
            or url.netloc != host
            or url.query
            or url.fragment
            or url.path != "/maifactory/openai/"
        ):
            raise ConfigurationError("Use /maifactory/openai/ on the matching mAI host; retired model routes are not supported.")
    if access == "application":
        for name in ("AZURE_TENANT_ID", "AZURE_CLIENT_ID"):
            if not values.get(name, "").strip():
                raise ConfigurationError(f"Set {name} from the approved app registration.")
    return Config(environment, access, team, host, scope, base, values.get("MAI_MODEL", "").strip())


def secret(name: str, environment: str) -> str:
    value = os.environ.get(name, "")
    if value.strip():
        return value
    import keyring

    module = type(keyring.get_keyring()).__module__
    allowed = ("keyring.backends.Windows", "keyring.backends.macOS", "keyring.backends.SecretService", "keyring.backends.kwallet")
    if not any(module == item or module.startswith(item + ".") for item in allowed):
        raise ConfigurationError("An approved OS credential store or injected secret is required.")
    value = keyring.get_password(f"worldbank-mai/{environment}", name)
    if not value or not value.strip():
        raise ConfigurationError(f"Provision {name} in the approved credential store.")
    return value


def make_token_provider(config: Config) -> Callable[[], str]:
    if config.access_type == "desktop":
        from itsai.platform.authentication import DesktopToken

        credential = DesktopToken()
        return lambda: credential.get_token(env=config.environment)
    from azure.identity import ClientSecretCredential, get_bearer_token_provider

    credential = ClientSecretCredential(
        tenant_id=os.environ["AZURE_TENANT_ID"],
        client_id=os.environ["AZURE_CLIENT_ID"],
        client_secret=secret("AZURE_CLIENT_SECRET", config.environment),
    )
    return get_bearer_token_provider(credential, config.scope)


def request_headers(config: Config) -> dict[str, str]:
    headers = {
        "x-team-name": config.team_name,
        "x-source-type": "interactive" if config.access_type == "desktop" else "job",
    }
    if config.access_type == "application":
        headers["Ocp-Apim-Subscription-Key"] = secret("APIM_SUBSCRIPTION_KEY", config.environment)
    return headers


def health(config: Config, provider: Callable[[], str]) -> None:
    import requests

    headers = request_headers(config)
    headers["Authorization"] = f"Bearer {provider()}"
    response = requests.get(
        f"https://{config.host}/conversationalai/platform/health/",
        headers=headers, timeout=30, allow_redirects=False,
    )
    if response.status_code != 200:
        raise ConfigurationError(f"Health request returned HTTP {response.status_code}; inspect locally without sharing credentials.")
    if response.json().get("status") != "healthy":
        raise ConfigurationError("Health response did not confirm healthy status.")


def ask(config: Config, provider: Callable[[], str], prompt: str) -> str:
    if not config.openai_base_url or not config.model:
        raise ConfigurationError("Verify and set MAI_OPENAI_BASE_URL and MAI_MODEL before a model call.")
    from openai import DefaultHttpxClient, OpenAI

    with OpenAI(
        base_url=config.openai_base_url,
        api_key=provider,
        default_headers=request_headers(config),
        timeout=30,
        max_retries=0,
        http_client=DefaultHttpxClient(follow_redirects=False),
    ) as client:
        response = client.responses.create(model=config.model, input=prompt, max_output_tokens=128)
    if isinstance(response.output_text, str) and response.output_text.strip():
        return response.output_text
    # Some gateway responses omit the SDK convenience text but retain text blocks.
    # Schema warnings can include response data, so do not emit them.
    parts = []
    for item in response.model_dump(warnings=False).get("output") or []:
        if not isinstance(item, dict):
            continue
        if (
            item.get("type") in {"output_text", "text", None}
            and isinstance(item.get("text"), str) and item["text"].strip()
        ):
            parts.append(item["text"])
        if item.get("type") in {"message", None}:
            for block in item.get("content") or []:
                if (
                    isinstance(block, dict) and block.get("type") in {"output_text", "text"}
                    and isinstance(block.get("text"), str) and block["text"].strip()
                ):
                    parts.append(block["text"])
    if not parts:
        raise ConfigurationError("No Responses text returned; check response status and the approved model contract locally.")
    return "\n".join(parts)


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("command", choices=("check", "health", "ask"))
    parser.add_argument("--prompt", default="Explain the World Bank mission in one sentence.")
    args = parser.parse_args()
    try:
        config = load_config()
        if args.command == "check":
            sys.stdout.write("Configuration valid. No credentials read and no network request made.\n")
        elif args.command == "health":
            health(config, make_token_provider(config))
            sys.stdout.write("Gateway healthy. Model permissions are not yet verified.\n")
        else:
            if not config.openai_base_url or not config.model:
                raise ConfigurationError("Verify and set MAI_OPENAI_BASE_URL and MAI_MODEL before login.")
            sys.stdout.write(ask(config, make_token_provider(config), args.prompt) + "\n")
        return 0
    except ConfigurationError as error:
        sys.stderr.write(str(error) + "\n")
    except Exception as error:
        status = getattr(error, "status_code", None)
        suffix = f" (HTTP {status})" if isinstance(status, int) else ""
        sys.stderr.write(f"mAI operation failed{suffix}. Check dependencies, access, and environment locally; no error body was logged.\n")
    return 1


if __name__ == "__main__":
    raise SystemExit(main())

# Explicit configuration. Sourcing this file does not read secrets or use network.
mai_config <- function(values = NULL) {
  setting <- function(name, default = "") {
    if (is.null(values)) return(trimws(Sys.getenv(name, unset = default)))
    if (!name %in% names(values)) return(default)
    value <- values[[name]]
    if (is.null(value) || !length(value)) default else trimws(value)
  }
  environment <- toupper(setting("MAI_ENV", "DEV"))
  hosts <- c(DEV = "azapimdev.worldbank.org", QA = "azapimqa.worldbank.org",
             PROD = "azapim.worldbank.org")
  if (!environment %in% names(hosts)) stop("MAI_ENV must be DEV, QA, or PROD.", call. = FALSE)
  access <- setting("MAI_ACCESS_TYPE")
  if (!access %in% c("desktop", "posit-connect")) {
    stop("Set MAI_ACCESS_TYPE to desktop or posit-connect for this starter.", call. = FALSE)
  }
  team <- setting("MAI_TEAM_NAME")
  if (!nzchar(team) || grepl("[^ -~]", team)) {
    stop("Set MAI_TEAM_NAME to an approved ASCII header value.", call. = FALSE)
  }
  source_type <- setting("MAI_SOURCE_TYPE", "interactive")
  if (!source_type %in% c("interactive", "job")) stop("Invalid MAI_SOURCE_TYPE.", call. = FALSE)
  host <- unname(hosts[[environment]])
  url <- setting("MAI_RESPONSES_URL")
  allowed <- paste0("https://", host, "/maifactory/openai/responses")
  if (nzchar(url) && !url %in% allowed) {
    stop("Use a verified Responses URL on the matching mAI host.", call. = FALSE)
  }
  list(environment = environment, access = access, team = team,
       source_type = source_type, host = host, responses_url = url,
       model = setting("MAI_MODEL"))
}

mai_token_provider <- function(config) {
  if (identical(config$access, "posit-connect")) {
    return(function() {
      tryCatch({
        api_key <- Sys.getenv("API_KEY")
        guid <- Sys.getenv("OAUTH_INTEGRATION_GUID")
        if (!nzchar(trimws(api_key)) || !nzchar(trimws(guid))) stop("Missing configuration")
        client <- connectapi::connect(server = "https://datanalytics-int.worldbank.org/",
                                      api_key = api_key)
        credentials <- connectapi::get_oauth_content_credentials(connect = client, audience = guid)
        token <- credentials$access_token
        if (!is.character(token) || length(token) != 1L || !nzchar(token)) stop("Missing token")
        token
      }, error = function(e) {
        stop("Connect OAuth failed. Check API_KEY, OAUTH_INTEGRATION_GUID, and content permissions locally.", call. = FALSE)
      })
    })
  }
  credential <- tryCatch({
    reticulate::import("itsai.platform.authentication")$DesktopToken()
  }, error = function(e) stop("Check the approved Python environment and private Desktop SDK.", call. = FALSE))
  function() {
    tryCatch(credential$get_token(env = config$environment),
             error = function(e) stop("Desktop login failed. Check approved access and network locally.", call. = FALSE))
  }
}

mai_perform <- function(config, token_provider, url, body = NULL) {
  allowed <- paste0("https://", config$host, c(
    "/conversationalai/platform/health/", "/maifactory/openai/responses"
  ))
  if (!url %in% allowed) stop("Unapproved request URL.", call. = FALSE)
  response <- tryCatch({
    request <- httr2::request(url) |>
      httr2::req_auth_bearer_token(token_provider()) |>
      httr2::req_headers(`x-team-name` = config$team, `x-source-type` = config$source_type) |>
      httr2::req_timeout(30) |>
      httr2::req_options(followlocation = FALSE) |>
      httr2::req_error(is_error = function(response) FALSE)
    if (!is.null(body)) request <- httr2::req_body_json(request, body)
    httr2::req_perform(request)
  }, error = function(e) {
    stop("mAI request failed. Check network, auth, route, and status locally; no response body was logged.", call. = FALSE)
  })
  status <- httr2::resp_status(response)
  if (status != 200L) stop(sprintf("mAI request returned HTTP %d; no response body was logged.", status), call. = FALSE)
  tryCatch(httr2::resp_body_json(response, simplifyVector = FALSE),
           error = function(e) stop("mAI returned an unexpected response format.", call. = FALSE))
}

mai_health <- function(config, token_provider) {
  result <- mai_perform(config, token_provider,
                        paste0("https://", config$host, "/conversationalai/platform/health/"))
  if (!identical(result$status, "healthy")) stop("Gateway health was not confirmed.", call. = FALSE)
  invisible(TRUE)
}

mai_response_text <- function(result) {
  text_value <- function(value) {
    if (is.character(value) && length(value) == 1L && !is.na(value) && nzchar(trimws(value))) {
      value
    } else character()
  }
  text <- character()
  if (is.list(result)) {
    text <- text_value(result$output_text)
    if (length(text)) return(text)
    for (item in result$output) {
      if (!is.list(item)) next
      if (isTRUE(item$type %in% c("output_text", "text"))) {
        text <- c(text, text_value(item$text))
      }
      if (!identical(item$type, "message")) next
      for (block in item$content) {
        if (is.list(block) && isTRUE(block$type %in% c("output_text", "text"))) {
          text <- c(text, text_value(block$text))
        }
      }
    }
  }
  if (!length(text)) stop("No Responses text blocks returned; check the verified schema and response status.", call. = FALSE)
  paste(text, collapse = "\n")
}

mai_ask <- function(config, token_provider, prompt) {
  if (!nzchar(config$responses_url) || !nzchar(config$model)) {
    stop("Verify and set MAI_RESPONSES_URL and MAI_MODEL before a model call.", call. = FALSE)
  }
  if (!is.character(prompt) || length(prompt) != 1L || is.na(prompt) || !nzchar(prompt)) {
    stop("Supply one nonempty prompt.", call. = FALSE)
  }
  result <- mai_perform(config, token_provider, config$responses_url,
                         list(model = config$model, input = prompt, max_output_tokens = 128L))
  mai_response_text(result)
}
